struct Case {QString body,initial,report,extra;QStringList inputs,outputs;QJsonArray numbers,strings;};
static Case fixture(const QString &mode,const QString &inner)
{
   Case c;
   if (mode=="Scalar") {c.body="function [out, copied] = Accept(input)\nCreate Variable out copied;\nBeginMissionSequence;\nout = 4 * input + 2;\ninput = input + 100;\ncopied = input;\n";c.inputs={"Number"};c.outputs={"Result","Copy"};c.report="Number Result Copy";c.numbers={2.5,12,102.5};c.initial=QString(c.body).replace("4 * input","3 * input");}
   else if (mode=="Array") {c.body="function [out] = Accept(input)\nCreate Array out[2,2];\nBeginMissionSequence;\nout(1,1) = input(2,2) + 2;\nout(1,2) = input(1,2) * 3;\nout(2,1) = input(2,1) - 4;\nout(2,2) = input(1,1) / 2;\ninput(1,1) = 999;\n";c.inputs={"A"};c.outputs={"OutA"};c.report="A(1,1) A(1,2) A(2,1) A(2,2) OutA(1,1) OutA(1,2) OutA(2,1) OutA(2,2)";c.numbers={1,2,3,4,6,6,-1,.5};}
   else if (mode=="String") {c.body="function [out] = Accept(input)\nCreate String out;\nBeginMissionSequence;\nout = input;\ninput = 'local changed';\n";c.inputs={"Text"};c.outputs={"ResultText"};c.report="Number";c.extra="Report States Text ResultText;\n";c.numbers={2.5};c.strings={QJsonObject{{"object","Text"},{"expected","alpha, beta"}},QJsonObject{{"object","ResultText"},{"expected","alpha, beta"}}};}
   else if (mode=="Object") {c.body="function [craft] = Accept(craft)\nBeginMissionSequence;\ncraft.X = craft.X + 12;\ncraft.VY = craft.VY - 0.25;\n";c.inputs={"Sat"};c.outputs={"Returned"};c.report="Sat.X Sat.Y Sat.Z Sat.VX Sat.VY Sat.VZ Returned.X Returned.Y Returned.Z Returned.VX Returned.VY Returned.VZ Sat.DryMass Returned.DryMass";c.numbers={1000,-200,300,1.25,-.5,.75,1012,-200,300,1.25,-.75,.75,371,371};}
   else if (mode=="Properties") {c.body="function [out, stamp] = Accept(input, epoch)\nCreate Variable out;\nCreate String stamp;\nBeginMissionSequence;\nout = input + 7;\nstamp = epoch;\n";c.inputs={"Sat.X","Sat.UTCGregorian"};c.outputs={"Returned.X","Returned.UTCGregorian"};c.report="Sat.X Returned.X";c.extra="Report States Sat.UTCGregorian Returned.UTCGregorian;\n";c.numbers={1000,1007};}
   else if (mode=="Literals") {c.body="function [out, text] = Accept(input, message)\nCreate Variable out;\nCreate String text;\nBeginMissionSequence;\nout = input * input - 1;\ntext = message;\n";c.inputs={"-3.5","'literal, comma'"};c.outputs={"Result","ResultText"};c.report="Number Result";c.extra="Report States ResultText;\n";c.numbers={2.5,11.25};c.strings={QJsonObject{{"object","ResultText"},{"expected","literal, comma"}}};}
   else if (mode=="NoInputs") {c.body="function [Shared] = Accept()\nGlobal Shared;\nBeginMissionSequence;\nShared = Shared + 3;\n";c.outputs={"Shared"};c.report="Shared";c.numbers={8};}
   else if (mode=="NoOutputs") {c.body="function Accept(input)\nGlobal Shared;\nBeginMissionSequence;\nShared = Shared + input;\ninput = 999;\n";c.inputs={"Number"};c.report="Number Shared";c.numbers={2.5,7.5};}
   else if (mode=="MissingOutput") {c.body="function [out] = Accept(input)\nCreate Variable out;\nBeginMissionSequence;\nout = input + 4;\n";c.inputs={"Number"};c.outputs={"Result"};c.report="Number Result";c.numbers={2.5,6.5};}
   else if (mode=="Nested") {c.body="function [out] = Accept(input)\nCreate GmatFunction Inner;\nInner.FunctionPath = '"+inner+"';\nCreate Variable out;\nBeginMissionSequence;\n[out] = Inner(input);\nout = out + 1;\n";c.inputs={"Number"};c.outputs={"Result"};c.report="Number Result";c.numbers={2.5,7.25};}
   else throw std::runtime_error("Unknown function I/O case");
   if (c.initial.isEmpty()) c.initial=c.body+"% Initial function revision\n";
   c.body+="% Function revision saved in actual GUI editor Δ\n";return c;
}
